import xml.etree.ElementTree as ET
NS={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
t=ET.parse('word/document.xml'); r=t.getroot()
body=r.find('w:body',NS)
def ptext(p):
    return ''.join(n.text or '' for n in p.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t'))
def pstyle(p):
    pPr=p.find('w:pPr',NS)
    if pPr is None: return ''
    s=pPr.find('w:pStyle',NS)
    return s.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val') if s is not None else ''
def walk(el, depth=0):
    for child in el:
        tag=child.tag.split('}')[1]
        if tag=='p':
            txt=ptext(child); st=pstyle(child)
            if txt.strip(): print(('  '*depth)+ (f'[{st}] ' if st else '') + txt)
        elif tag=='tbl':
            print('  '*depth+'--- TABLE ---')
            for tr in child.findall('w:tr',NS):
                cells=[]
                for tc in tr.findall('w:tc',NS):
                    ct=' '.join(ptext(p) for p in tc.findall('w:p',NS))
                    cells.append(ct.strip())
                print('  '*depth+' | '.join(cells))
            print('  '*depth+'--- /TABLE ---')
        elif tag=='sdt':
            walk(child, depth)
walk(body)
